<?php
declare(strict_types=1);
namespace App\Services;
use App\Config\Database;use App\Support\Reference;use PDO;use RuntimeException;
final class LoadService{
 private static function companyId():int{$c=Auth::context()['companies'][0]??null;if(!$c)throw new RuntimeException('An active company membership is required.');return(int)$c['company_id'];}
 private static function roleId():?int{foreach(Auth::context()['roles']??[] as $r)if($r['role_code']==='SHIPPER')return(int)$r['user_role_id'];return null;}
 public static function counts():array{$st=Database::connection()->prepare("SELECT COUNT(*) total,SUM(current_status='draft') drafts,SUM(current_status='submitted') submitted FROM loads WHERE customer_company_id=? AND status='active'");$st->execute([self::companyId()]);$r=$st->fetch();return['total'=>(int)($r['total']??0),'drafts'=>(int)($r['drafts']??0),'submitted'=>(int)($r['submitted']??0)];}
 public static function all():array{$st=Database::connection()->prepare("SELECT l.load_id,l.load_ref,l.cargo_summary,l.requested_pickup_from,l.current_status,l.updated_at,oa.city origin_city,da.city destination_city FROM loads l JOIN addresses oa ON oa.address_id=l.origin_address_id JOIN addresses da ON da.address_id=l.destination_address_id WHERE l.customer_company_id=? AND l.status='active' ORDER BY l.created_at DESC");$st->execute([self::companyId()]);return$st->fetchAll();}
 public static function find(int$id):?array{$sql="SELECT l.*,oa.line_1 origin_line_1,oa.line_2 origin_line_2,oa.city origin_city,oa.region origin_region,oa.country_code origin_country,da.line_1 destination_line_1,da.line_2 destination_line_2,da.city destination_city,da.region destination_region,da.country_code destination_country,lv.load_version_id,lv.version_no,lv.status version_status,lr.clarification_request,lr.clarification_requested_at,lr.decision_code,lr.decision_reason,lr.decided_at,li.load_item_id,li.description item_description,li.cargo_category_code,li.quantity,li.unit_code,li.weight_value,li.weight_unit_code,li.packaging_details,li.handling_requirements FROM loads l JOIN addresses oa ON oa.address_id=l.origin_address_id JOIN addresses da ON da.address_id=l.destination_address_id JOIN load_versions lv ON lv.load_id=l.load_id JOIN load_items li ON li.load_version_id=lv.load_version_id AND li.line_no=1 LEFT JOIN load_reviews lr ON lr.load_version_id=lv.load_version_id WHERE l.load_id=? AND l.customer_company_id=? ORDER BY lv.version_no DESC LIMIT 1";$st=Database::connection()->prepare($sql);$st->execute([$id,self::companyId()]);$r=$st->fetch();return$r?:null;}
 private static function clean(array$d):array{$required=['origin_line_1','origin_city','origin_country','destination_line_1','destination_city','destination_country','cargo_summary','item_description','quantity','unit_code'];foreach($required as$k)if(trim((string)($d[$k]??''))==='')throw new RuntimeException('Complete all required load and cargo fields.');foreach(['origin_country','destination_country']as$k)if(!preg_match('/^[A-Z]{2}$/',strtoupper(trim((string)$d[$k]))))throw new RuntimeException('Country codes must contain two letters.');$qty=(float)$d['quantity'];if($qty<=0)throw new RuntimeException('Cargo quantity must be greater than zero.');$pickupFrom=self::dateValue($d['requested_pickup_from']??null);$pickupTo=self::dateValue($d['requested_pickup_to']??null);$deliveryFrom=self::dateValue($d['requested_delivery_from']??null);$deliveryTo=self::dateValue($d['requested_delivery_to']??null);if($pickupFrom&&$pickupTo&&$pickupTo<$pickupFrom)throw new RuntimeException('Pickup end cannot be before pickup start.');if($deliveryFrom&&$deliveryTo&&$deliveryTo<$deliveryFrom)throw new RuntimeException('Delivery end cannot be before delivery start.');return['origin_line_1'=>trim($d['origin_line_1']),'origin_line_2'=>trim((string)($d['origin_line_2']??''))?:null,'origin_city'=>trim($d['origin_city']),'origin_region'=>trim((string)($d['origin_region']??''))?:null,'origin_country'=>strtoupper(trim($d['origin_country'])),'destination_line_1'=>trim($d['destination_line_1']),'destination_line_2'=>trim((string)($d['destination_line_2']??''))?:null,'destination_city'=>trim($d['destination_city']),'destination_region'=>trim((string)($d['destination_region']??''))?:null,'destination_country'=>strtoupper(trim($d['destination_country'])),'cargo_summary'=>trim($d['cargo_summary']),'pickup_from'=>$pickupFrom,'pickup_to'=>$pickupTo,'delivery_from'=>$deliveryFrom,'delivery_to'=>$deliveryTo,'insurance'=>isset($d['insurance_required'])?1:0,'special'=>trim((string)($d['special_instructions']??''))?:null,'item_description'=>trim($d['item_description']),'category'=>trim((string)($d['cargo_category_code']??''))?:null,'quantity'=>$qty,'unit_code'=>strtoupper(trim($d['unit_code'])),'weight'=>trim((string)($d['weight_value']??''))!==''?(float)$d['weight_value']:null,'weight_unit'=>trim((string)($d['weight_unit_code']??''))?:null,'packaging'=>trim((string)($d['packaging_details']??''))?:null,'handling'=>trim((string)($d['handling_requirements']??''))?:null];}
 private static function dateValue(mixed$v):?string{$v=trim((string)$v);if($v==='')return null;$t=strtotime($v);if($t===false)throw new RuntimeException('One or more dates are invalid.');return gmdate('Y-m-d H:i:s',$t);}
 private static function snapshot(array$d):string{return json_encode($d,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);}
 public static function create(array$data,int$userId):int{if(!Auth::can('LOAD_CREATE_OWN'))throw new RuntimeException('You do not have permission to create loads.');$d=self::clean($data);$pdo=Database::connection();$pdo->beginTransaction();try{$addr="INSERT INTO addresses(address_ref,line_1,line_2,city,region,country_code,status,created_by_user_id,updated_by_user_id)VALUES(?,?,?,?,?,?,'active',?,?)";$st=$pdo->prepare($addr);$st->execute([Reference::make('ADR'),$d['origin_line_1'],$d['origin_line_2'],$d['origin_city'],$d['origin_region'],$d['origin_country'],$userId,$userId]);$oa=(int)$pdo->lastInsertId();$st->execute([Reference::make('ADR'),$d['destination_line_1'],$d['destination_line_2'],$d['destination_city'],$d['destination_region'],$d['destination_country'],$userId,$userId]);$da=(int)$pdo->lastInsertId();$ref=Reference::make('LOAD');$st=$pdo->prepare("INSERT INTO loads(load_ref,customer_company_id,origin_address_id,destination_address_id,cargo_summary,requested_pickup_from,requested_pickup_to,requested_delivery_from,requested_delivery_to,insurance_required,special_instructions,source_service_type,current_status,status,created_by_user_id,updated_by_user_id)VALUES(?,?,?,?,?,?,?,?,?,?,?,'core_freight','draft','active',?,?)");$st->execute([$ref,self::companyId(),$oa,$da,$d['cargo_summary'],$d['pickup_from'],$d['pickup_to'],$d['delivery_from'],$d['delivery_to'],$d['insurance'],$d['special'],$userId,$userId]);$id=(int)$pdo->lastInsertId();$st=$pdo->prepare("INSERT INTO load_versions(load_version_ref,load_id,version_no,authored_by_user_id,source_channel,snapshot_json,status,created_by_user_id,updated_by_user_id)VALUES(?,?,1,?,'web',?,'draft',?,?)");$st->execute([Reference::make('LDV'),$id,$userId,self::snapshot($d),$userId,$userId]);$vid=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO load_items(load_item_ref,load_id,load_version_id,line_no,description,cargo_category_code,quantity,unit_code,weight_value,weight_unit_code,packaging_details,handling_requirements,status,created_by_user_id,updated_by_user_id)VALUES(?,?,?,1,?,?,?,?,?,?,?,?,'active',?,?)")->execute([Reference::make('LIT'),$id,$vid,$d['item_description'],$d['category'],$d['quantity'],$d['unit_code'],$d['weight'],$d['weight_unit'],$d['packaging'],$d['handling'],$userId,$userId]);self::history($pdo,$id,null,'draft',$userId,'Load draft created');self::audit($pdo,'LOAD_DRAFT_CREATED',$id,$userId);$pdo->commit();return$id;}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
 public static function update(int$id,array$data,int$userId,int$rowVersion):void{if(!Auth::can('LOAD_UPDATE_DRAFT_OWN'))throw new RuntimeException('You do not have permission to edit this load.');$d=self::clean($data);$load=self::find($id);if(!$load||$load['current_status']!=='draft')throw new RuntimeException('Only your own draft load may be edited.');$pdo=Database::connection();$pdo->beginTransaction();try{$addr="UPDATE addresses SET line_1=?,line_2=?,city=?,region=?,country_code=?,updated_by_user_id=?,row_version=row_version+1 WHERE address_id=?";$pdo->prepare($addr)->execute([$d['origin_line_1'],$d['origin_line_2'],$d['origin_city'],$d['origin_region'],$d['origin_country'],$userId,$load['origin_address_id']]);$pdo->prepare($addr)->execute([$d['destination_line_1'],$d['destination_line_2'],$d['destination_city'],$d['destination_region'],$d['destination_country'],$userId,$load['destination_address_id']]);$st=$pdo->prepare("UPDATE loads SET cargo_summary=?,requested_pickup_from=?,requested_pickup_to=?,requested_delivery_from=?,requested_delivery_to=?,insurance_required=?,special_instructions=?,updated_by_user_id=?,row_version=row_version+1 WHERE load_id=? AND customer_company_id=? AND current_status='draft' AND row_version=?");$st->execute([$d['cargo_summary'],$d['pickup_from'],$d['pickup_to'],$d['delivery_from'],$d['delivery_to'],$d['insurance'],$d['special'],$userId,$id,self::companyId(),$rowVersion]);if($st->rowCount()!==1)throw new RuntimeException('This draft was changed elsewhere. Refresh before editing again.');$pdo->prepare("UPDATE load_versions SET snapshot_json=?,updated_by_user_id=?,row_version=row_version+1 WHERE load_version_id=? AND status='draft'")->execute([self::snapshot($d),$userId,$load['load_version_id']]);$pdo->prepare("UPDATE load_items SET description=?,cargo_category_code=?,quantity=?,unit_code=?,weight_value=?,weight_unit_code=?,packaging_details=?,handling_requirements=?,updated_by_user_id=?,row_version=row_version+1 WHERE load_item_id=?")->execute([$d['item_description'],$d['category'],$d['quantity'],$d['unit_code'],$d['weight'],$d['weight_unit'],$d['packaging'],$d['handling'],$userId,$load['load_item_id']]);self::audit($pdo,'LOAD_DRAFT_UPDATED',$id,$userId);$pdo->commit();}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
 public static function submit(int$id,int$userId):void{if(!Auth::can('LOAD_SUBMIT_OWN'))throw new RuntimeException('You do not have permission to submit loads.');$load=self::find($id);if(!$load||$load['current_status']!=='draft')throw new RuntimeException('Only your own draft load may be submitted.');$pdo=Database::connection();$pdo->beginTransaction();try{$st=$pdo->prepare("UPDATE loads SET current_status='submitted',updated_by_user_id=?,row_version=row_version+1 WHERE load_id=? AND customer_company_id=? AND current_status='draft'");$st->execute([$userId,$id,self::companyId()]);if($st->rowCount()!==1)throw new RuntimeException('The load is no longer an editable draft.');$pdo->prepare("UPDATE load_versions SET status='submitted',submission_reason='Submitted by Shipper for McCollins review',submitted_at=UTC_TIMESTAMP(6),updated_by_user_id=? WHERE load_version_id=? AND status='draft'")->execute([$userId,$load['load_version_id']]);self::history($pdo,$id,'draft','submitted',$userId,'Submitted by Shipper for McCollins review');self::audit($pdo,'LOAD_SUBMITTED',$id,$userId);$pdo->commit();}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
 public static function respondToClarification(int$id,array$data,int$userId,int$rowVersion):void{
  if(!Auth::can('LOAD_CLARIFICATION_RESPOND_OWN'))throw new RuntimeException('You do not have permission to respond to clarification.');
  $d=self::clean($data);$response=trim((string)($data['clarification_response']??''));if(strlen($response)<5||strlen($response)>2000)throw new RuntimeException('Response note must be between 5 and 2000 characters.');
  $pdo=Database::connection();$pdo->beginTransaction();try{
   $companyId=self::companyId();
   $st=$pdo->prepare("SELECT l.*,lv.load_version_id,lv.version_no,lr.load_review_id,lr.reviewer_user_id,lr.reviewer_user_role_id FROM loads l JOIN load_versions lv ON lv.load_id=l.load_id AND lv.version_no=(SELECT MAX(v.version_no) FROM load_versions v WHERE v.load_id=l.load_id) JOIN load_reviews lr ON lr.load_version_id=lv.load_version_id WHERE l.load_id=? AND l.customer_company_id=? AND l.status='active' FOR UPDATE");$st->execute([$id,$companyId]);$load=$st->fetch();
   if(!$load||$load['current_status']!=='clarification_required')throw new RuntimeException('This company load is not awaiting clarification.');
   $addr="INSERT INTO addresses(address_ref,line_1,line_2,city,region,country_code,status,created_by_user_id,updated_by_user_id)VALUES(?,?,?,?,?,?,'active',?,?)";$ast=$pdo->prepare($addr);
   $ast->execute([Reference::make('ADR'),$d['origin_line_1'],$d['origin_line_2'],$d['origin_city'],$d['origin_region'],$d['origin_country'],$userId,$userId]);$oa=(int)$pdo->lastInsertId();
   $ast->execute([Reference::make('ADR'),$d['destination_line_1'],$d['destination_line_2'],$d['destination_city'],$d['destination_region'],$d['destination_country'],$userId,$userId]);$da=(int)$pdo->lastInsertId();
   $st=$pdo->prepare("UPDATE loads SET origin_address_id=?,destination_address_id=?,cargo_summary=?,requested_pickup_from=?,requested_pickup_to=?,requested_delivery_from=?,requested_delivery_to=?,insurance_required=?,special_instructions=?,current_status='under_review',updated_by_user_id=?,row_version=row_version+1 WHERE load_id=? AND customer_company_id=? AND current_status='clarification_required' AND row_version=?");
   $st->execute([$oa,$da,$d['cargo_summary'],$d['pickup_from'],$d['pickup_to'],$d['delivery_from'],$d['delivery_to'],$d['insurance'],$d['special'],$userId,$id,$companyId,$rowVersion]);if($st->rowCount()!==1)throw new RuntimeException('The load changed elsewhere. Refresh before responding.');
   $snapshot=$d;$snapshot['clarification_response']=$response;$next=(int)$load['version_no']+1;
   $pdo->prepare("INSERT INTO load_versions(load_version_ref,load_id,version_no,authored_by_user_id,source_channel,snapshot_json,submission_reason,submitted_at,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,?,'web',?,?,UTC_TIMESTAMP(6),'under_review',?,?)")->execute([Reference::make('LDV'),$id,$next,$userId,self::snapshot($snapshot),'Shipper clarification response: '.$response,$userId,$userId]);$vid=(int)$pdo->lastInsertId();
   $pdo->prepare("INSERT INTO load_items(load_item_ref,load_id,load_version_id,line_no,description,cargo_category_code,quantity,unit_code,weight_value,weight_unit_code,packaging_details,handling_requirements,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,1,?,?,?,?,?,?,?,?,'active',?,?)")->execute([Reference::make('LIT'),$id,$vid,$d['item_description'],$d['category'],$d['quantity'],$d['unit_code'],$d['weight'],$d['weight_unit'],$d['packaging'],$d['handling'],$userId,$userId]);
   $pdo->prepare("UPDATE load_reviews SET clarification_response=?,clarification_responded_by_user_id=?,response_load_version_id=?,clarification_responded_at=UTC_TIMESTAMP(6),updated_by_user_id=?,row_version=row_version+1 WHERE load_review_id=? AND review_status='clarification_required'")->execute([$response,$userId,$vid,$userId,$load['load_review_id']]);
   $pdo->prepare("INSERT INTO load_reviews(load_review_ref,load_id,load_version_id,reviewer_user_id,reviewer_user_role_id,review_status,started_at,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,?,?,'under_review',UTC_TIMESTAMP(6),'active',?,?)")->execute([Reference::make('LRV'),$id,$vid,$load['reviewer_user_id'],$load['reviewer_user_role_id'],$userId,$userId]);
   self::history($pdo,$id,'clarification_required','under_review',$userId,'Clarification response submitted: '.$response);self::audit($pdo,'LOAD_CLARIFICATION_RESPONDED',$id,$userId);$pdo->commit();
  }catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}
 }
 private static function history(PDO$pdo,int$id,?string$old,string$new,int$uid,string$reason):void{$pdo->prepare("INSERT INTO status_history(status_history_ref,entity_type,entity_id_value,previous_status,new_status,actor_user_id,actor_user_role_id,source_channel,reason,occurred_at,status,created_by_user_id)VALUES(?,'load',?,?,?,?,?,'web',?,UTC_TIMESTAMP(6),'active',?)")->execute([Reference::make('STH'),$id,$old,$new,$uid,self::roleId(),$reason,$uid]);}
 private static function audit(PDO$pdo,string$action,int$id,int$uid):void{$meta=json_encode(['action_code'=>$action,'entity_type'=>'load','entity_id'=>$id,'source'=>'web'],JSON_THROW_ON_ERROR);$pdo->prepare("INSERT INTO audit_events(audit_event_ref,metadata_json,status,created_by_user_id)VALUES(?,?,'active',?)")->execute([Reference::make('AUD'),$meta,$uid]);}
}
